// SPDX-License-Identifier: Apache-2.0
//! The canonical WAR IR (SAS §63) and the Compilation Basis it is built from
//! (§14).
//!
//! §63: "The canonical IR is a typed semantic object, not a Markdown AST."

use serde::{Deserialize, Serialize};

use crate::canonical::{CanonicalError, sha256_digest};
use crate::digest::DigestDomain;

/// The API version every canonical document carries (§63).
pub const API_VERSION: &str = "oh.war/v1";
/// The record kind (§4.2).
pub const KIND: &str = "work_authorization_record";

/// The schema pack this build implements (§64).
pub const SCHEMA_PACK_ID: &str = "openwarrant-schema-pack";
// `source_and_composition.scope` is an optional, contract-bearing field added
// after 0.1.0. That is a backward-compatible schema capability, so it is a
// minor pack release rather than silently relabelling 0.1.0 documents.
pub const SCHEMA_PACK_VERSION: &str = "0.2.0";

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Pins schema, vocabulary, profile, and state-machine versions (§64).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FormatBasis {
    pub package_id: String,
    pub version: String,
    pub root_schema_id: String,
    pub profile_schema_id: String,
    /// §14 / §101.6 — the SAS revision this compilation is pinned against.
    /// Absent, not null, when no revision is recorded, so that a repository
    /// that has never pinned its document keeps every digest it has.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sas_revision: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sas_digest: Option<String>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// UUID, aliases, enterprise ID, title, profile (§63.2).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Identity {
    pub uuid: String,
    pub local_alias: String,
    /// Absent until Knowledge Fabric allocates one (§12.4). Serialised as absent
    /// rather than as `""`, because "no official identity" and "an official
    /// identity that is the empty string" are different claims.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub enterprise_id: Option<String>,
    pub title: String,
    pub profile: String,
    pub assurance_level: String,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// One atom as it entered the compilation (§63.3).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SourceAtom {
    pub ordinal: u32,
    pub role: String,
    pub jurisdiction: String,
    pub source: String,
    /// SHA-256 over the atom's exact source bytes (§62.2, §65 `atom_source_digest`).
    pub atom_source_digest: String,
    pub required: bool,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// One machine-readable scope sidecar that participates in the contract.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SourceScope {
    /// Repository-relative source location.
    pub source: String,
    /// SHA-256 over exact sidecar bytes.
    pub scope_source_digest: String,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Workspace Basis and composition (§63.3, §14).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SourceAndComposition {
    pub manifest_source: String,
    pub manifest_digest: String,
    pub atoms: Vec<SourceAtom>,
    /// Optional because scope was introduced after existing Warrants. Its
    /// presence and digest are contract-bearing; it is never advisory data.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub scope: Option<SourceScope>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Typed relation edges (§63.4).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Relations {
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub implements: Vec<ImplementsEdge>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub roadmap: Vec<String>,
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub parents: Vec<ParentEdge>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ImplementsEdge {
    pub r#ref: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub contribution: Option<String>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ParentEdge {
    pub r#ref: String,
    pub contract_revision: u32,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub contract_digest: Option<String>,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// Digests and checkpoints (§63.11).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Integrity {
    pub algorithm: String,
    pub workspace_basis_digest: String,
    pub composition_revision_digest: String,
}

#[cfg_attr(feature = "schema", derive(schemars::JsonSchema))]
/// The canonical WAR IR (§63).
///
/// # Absent is not empty
///
/// Sections Phase 1 does not populate — `execution`, `assurance_case`,
/// `resolution` — are `Option` and are OMITTED from the canonical JSON, not
/// serialised as `{}`.
///
/// This distinction is load-bearing and is the single highest-value invariant in
/// the type. If absent and empty serialised identically, the first Warrant to
/// populate `execution` would change the canonical bytes — and therefore the
/// digest — of every Warrant compiled before it, retroactively invalidating
/// digests that were correct when minted. `absent_and_empty_differ` pins it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct WarIr {
    pub api_version: String,
    pub kind: String,
    pub format_basis: FormatBasis,
    pub identity: Identity,
    pub source_and_composition: SourceAndComposition,
    pub relations: Relations,
    pub integrity: Integrity,
    /// Which §28.5 elements the contract digest covers (OW-ADR-0004).
    pub contract_coverage: openwarrant_core::ContractCoverage,
    /// The contract revision this compilation represents (§28).
    pub contract_revision: u32,

    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub execution: Option<serde_json::Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub assurance_case: Option<serde_json::Value>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub resolution: Option<serde_json::Value>,
    /// Unknown namespaced extensions survive a round trip (§69.4, §91.1 test 5).
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub extensions: Option<serde_json::Value>,
}

impl WarIr {
    /// The contract digest — the identity of what was authorized (§65).
    ///
    /// Computed over identity, composition, and relations. It deliberately does
    /// NOT include the generated projections: §91.1 test 3 requires that
    /// changing how a document renders cannot change the contract digest,
    /// because rendering is downstream of meaning.
    pub fn contract_digest(&self) -> Result<String, CanonicalError> {
        #[derive(Serialize)]
        struct ContractView<'a> {
            /// OW-ADR-0004: the §28.5 elements this digest actually covers, IN
            /// the preimage. A digest over five elements and one over seventeen
            /// are therefore different values even for identical content, so a
            /// partial digest can never be mistaken for a complete one.
            coverage: &'a openwarrant_core::ContractCoverage,
            format_basis: &'a FormatBasis,
            identity: &'a Identity,
            source_and_composition: &'a SourceAndComposition,
            relations: &'a Relations,
        }
        sha256_digest(
            DigestDomain::Contract,
            &ContractView {
                coverage: &self.contract_coverage,
                format_basis: &self.format_basis,
                identity: &self.identity,
                source_and_composition: &self.source_and_composition,
                relations: &self.relations,
            },
        )
    }

    /// The §28.5 elements a compilation can cover today.
    ///
    /// Deliberately a function rather than a constant: each element joins as its
    /// Warrant lands (deliverables OW-WAR-0015, obligations OW-WAR-0016, gates
    /// OW-WAR-0019, capabilities OW-WAR-0023), and every addition MOVES the
    /// contract digest. That churn is the point — a Warrant authorized under a
    /// five-element contract was authorized over less than one authorized under
    /// seventeen, and the digest must say so.
    #[must_use]
    pub fn current_coverage() -> openwarrant_core::ContractCoverage {
        use openwarrant_core::ContractElement as E;
        openwarrant_core::ContractCoverage::new([
            E::Intent,
            E::Scope,
            E::BasisRequirements,
            E::Assumptions,
            E::Constraints,
            E::AdrReferences,
            E::Milestones,
            E::Stages,
        ])
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::canonical::to_canonical_string;

    fn ir() -> WarIr {
        WarIr {
            api_version: API_VERSION.to_owned(),
            kind: KIND.to_owned(),
            format_basis: FormatBasis {
                package_id: SCHEMA_PACK_ID.to_owned(),
                version: SCHEMA_PACK_VERSION.to_owned(),
                root_schema_id: KIND.to_owned(),
                profile_schema_id: "delivery".to_owned(),
                sas_revision: None,
                sas_digest: None,
            },
            identity: Identity {
                uuid: "01a018db-19fc-7f2a-8e39-69730f255e33".to_owned(),
                local_alias: "OW-WAR-0001".to_owned(),
                enterprise_id: None,
                title: "A warrant".to_owned(),
                profile: "delivery".to_owned(),
                assurance_level: "basic".to_owned(),
            },
            source_and_composition: SourceAndComposition {
                manifest_source: "docs/warrants/OW-WAR-0001/manifest.toml".to_owned(),
                manifest_digest: "0".repeat(64),
                atoms: vec![],
                scope: None,
            },
            relations: Relations {
                implements: vec![],
                roadmap: vec![],
                parents: vec![],
            },
            integrity: Integrity {
                algorithm: "sha256".to_owned(),
                workspace_basis_digest: "1".repeat(64),
                composition_revision_digest: "2".repeat(64),
            },
            contract_coverage: WarIr::current_coverage(),
            contract_revision: 1,
            execution: None,
            assurance_case: None,
            resolution: None,
            extensions: None,
        }
    }

    /// THE invariant. An absent section and an empty one must not serialise the
    /// same way, or populating a section later silently reprices every digest
    /// minted before it.
    #[test]
    fn absent_and_empty_differ() {
        let absent = ir();
        let mut empty = ir();
        empty.execution = Some(serde_json::json!({}));

        let a = to_canonical_string(&absent).expect("canonicalizes");
        let e = to_canonical_string(&empty).expect("canonicalizes");

        assert!(
            !a.contains("execution"),
            "an absent section must be omitted entirely, got: {a}"
        );
        assert!(
            e.contains("\"execution\":{}"),
            "an empty section must be present and empty, got: {e}"
        );
        assert_ne!(a, e, "absent and empty must never canonicalize alike");
        assert_ne!(
            absent.contract_digest().expect("digest"),
            // The contract view excludes execution, so this pair SHOULD match;
            // asserted below instead. Here we only compare the full documents.
            {
                let mut other = ir();
                other.identity.title = "A different warrant".to_owned();
                other.contract_digest().expect("digest")
            }
        );
    }

    #[test]
    fn pre_scope_documents_remain_readable_under_the_minor_schema_bump() {
        let mut value = serde_json::to_value(ir()).expect("serializes IR");
        value["format_basis"]["version"] = serde_json::json!("0.1.0");
        value["source_and_composition"]
            .as_object_mut()
            .expect("source composition object")
            .remove("scope");

        let parsed: WarIr = serde_json::from_value(value).expect("reads pre-scope IR");
        assert_eq!(SCHEMA_PACK_VERSION, "0.2.0");
        assert_eq!(parsed.format_basis.version, "0.1.0");
        assert!(parsed.source_and_composition.scope.is_none());
        let reserialized = serde_json::to_value(&parsed).expect("reserializes IR");
        assert!(
            reserialized["source_and_composition"]
                .get("scope")
                .is_none(),
            "absent scope sidecar must remain omitted"
        );
    }

    /// §91.1 test 3: how a document renders cannot change what was authorized.
    #[test]
    fn generated_sections_do_not_move_the_contract_digest() {
        let bare = ir();
        let mut with_generated = ir();
        with_generated.execution = Some(serde_json::json!({"attempts": [1, 2, 3]}));
        with_generated.resolution = Some(serde_json::json!({"verdict": "passed"}));

        assert_eq!(
            bare.contract_digest().expect("digest"),
            with_generated.contract_digest().expect("digest"),
            "execution and resolution are downstream of the contract"
        );
    }

    /// Changing anything the contract IS must move its digest.
    #[test]
    fn contract_content_moves_the_contract_digest() {
        let base = ir();
        let baseline = base.contract_digest().expect("digest");

        let mut retitled = ir();
        retitled.identity.title = "Something else".to_owned();
        assert_ne!(baseline, retitled.contract_digest().expect("digest"));

        let mut reprofiled = ir();
        reprofiled.identity.profile = "decision".to_owned();
        assert_ne!(baseline, reprofiled.contract_digest().expect("digest"));

        let mut reparented = ir();
        reparented.relations.parents.push(ParentEdge {
            r#ref: "war://01a018db-19fc-7f34-92db-54b2dca5446d".to_owned(),
            contract_revision: 1,
            contract_digest: None,
        });
        assert_ne!(baseline, reparented.contract_digest().expect("digest"));
    }

    #[test]
    fn api_version_and_kind_are_pinned() {
        let canonical = to_canonical_string(&ir()).expect("canonicalizes");
        assert!(canonical.contains(r#""api_version":"oh.war/v1""#));
        assert!(canonical.contains(r#""kind":"work_authorization_record""#));
    }

    /// A document we can write must be a document we can read.
    ///
    /// This caught a real defect: `Relations` and several `Option` fields
    /// carried `skip_serializing_if` without `default`, so a minimal IR
    /// serialised fine and then failed to deserialise with "missing field
    /// implements". §68.3 requires export→import→export to preserve semantic
    /// identity, and that is impossible if the import half rejects our own
    /// output.
    ///
    /// Kept as a MINIMAL fixture on purpose — every optional field empty or
    /// absent — because that is the shape that exercises every
    /// `skip_serializing_if`. A populated fixture would have passed while the
    /// bug was live.
    #[test]
    fn a_minimal_ir_round_trips_through_its_own_canonical_form() {
        let minimal = ir();
        let json = to_canonical_string(&minimal).expect("canonicalizes");
        let back: WarIr = serde_json::from_str(&json)
            .unwrap_or_else(|e| panic!("our own canonical output must deserialize: {e}\n{json}"));
        assert_eq!(back, minimal);
        // And re-exporting must reproduce the same bytes (§68.3).
        assert_eq!(to_canonical_string(&back).expect("canonicalizes"), json);
    }

    /// §91.1 test 5: unknown namespaced extensions survive a round trip.
    #[test]
    fn extensions_survive_a_round_trip() {
        let mut with_ext = ir();
        with_ext.extensions = Some(serde_json::json!({"x.lab": {"protocol": "A"}}));
        let json = to_canonical_string(&with_ext).expect("canonicalizes");
        let back: WarIr = serde_json::from_str(&json).expect("round trips");
        assert_eq!(back.extensions, with_ext.extensions);
        assert_eq!(back, with_ext);
    }

    /// An absent enterprise ID is absent, never the empty string (§12.4).
    #[test]
    fn absent_enterprise_id_is_omitted_not_empty() {
        let canonical = to_canonical_string(&ir()).expect("canonicalizes");
        assert!(!canonical.contains("enterprise_id"));
    }

    #[test]
    fn canonical_output_is_stable_across_two_computations() {
        let first = to_canonical_string(&ir()).expect("canonicalizes");
        let second = to_canonical_string(&ir()).expect("canonicalizes");
        assert_eq!(first, second);
    }
}

// SPDX-License-Identifier: Apache-2.0
//! RFC 8785 canonicalization and domain-separated digests (SAS §65).
//!
//! Implementation selected by OW-ADR-0001 on measured conformance.

use serde::Serialize;

use crate::digest::{DigestDomain, sha256_hex};

#[derive(Debug, thiserror::Error)]
pub enum CanonicalError {
    #[error("value could not be canonicalized as RFC 8785 JSON: {0}")]
    Canonicalize(#[from] serde_json::Error),
    /// `schemas/pack.json` does not declare the version inside every contract
    /// digest (OW-WAR-0032): nothing compiles until the pack and the format
    /// agree.
    #[error(
        "the committed schema pack does not declare version {expected}, the one inside every contract digest; regenerate it with `war schemas` (cargo feature `schema`) or restore it"
    )]
    SchemaPack { expected: String },
}

/// Canonicalize a serializable value to RFC 8785 JSON bytes.
pub fn to_canonical_bytes<T: Serialize>(value: &T) -> Result<Vec<u8>, CanonicalError> {
    Ok(serde_jcs::to_vec(value)?)
}

/// Canonicalize a serializable value to an RFC 8785 JSON string.
pub fn to_canonical_string<T: Serialize>(value: &T) -> Result<String, CanonicalError> {
    Ok(serde_jcs::to_string(value)?)
}

/// The domain-separated preimage a digest is computed over (SAS §65.2).
///
/// Field names are `digest_domain` and `payload` exactly as the SAS writes them.
/// Their canonical order is fixed by RFC 8785's key sort, not by this struct's
/// declaration order, so the preimage cannot drift if the fields are reordered
/// here.
#[derive(Debug, Serialize)]
struct Preimage<'a, T: Serialize> {
    digest_domain: &'a str,
    payload: &'a T,
}

/// The exact bytes hashed for `domain` over `payload`.
///
/// Exposed rather than kept private because a digest nobody can reproduce is a
/// digest nobody can audit: given a disagreement between two implementations,
/// the first question is always "what did you hash?"
pub fn preimage_bytes<T: Serialize>(
    domain: DigestDomain,
    payload: &T,
) -> Result<Vec<u8>, CanonicalError> {
    to_canonical_bytes(&Preimage {
        digest_domain: domain.as_uri(),
        payload,
    })
}

/// SHA-256 over the domain-separated canonical preimage, lowercase hex.
///
/// §65.1: the algorithm is always explicit. This function is SHA-256 and says so
/// in its name; a future algorithm gets a new function rather than a flag, so no
/// caller can compute a digest without knowing which one it got.
pub fn sha256_digest<T: Serialize>(
    domain: DigestDomain,
    payload: &T,
) -> Result<String, CanonicalError> {
    Ok(sha256_hex(&preimage_bytes(domain, payload)?))
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    /// The official cyberphone/json-canonicalization vectors, vendored under
    /// `conformance/rfc8785/`. External expectations: an implementation-derived
    /// snapshot would assert only that we are self-consistent.
    #[test]
    fn official_rfc8785_vectors() {
        let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/../../conformance/rfc8785");
        let names = [
            "arrays",
            "french",
            "structures",
            "unicode",
            "values",
            "weird",
        ];
        let mut checked = 0;
        for name in names {
            let input = std::fs::read_to_string(format!("{dir}/in-{name}.json"))
                .unwrap_or_else(|e| panic!("missing vector in-{name}.json: {e}"));
            let expected = std::fs::read_to_string(format!("{dir}/out-{name}.json"))
                .unwrap_or_else(|e| panic!("missing vector out-{name}.json: {e}"));
            let value: serde_json::Value =
                serde_json::from_str(&input).expect("vector input parses");
            assert_eq!(
                to_canonical_string(&value).expect("canonicalizes"),
                expected.trim_end_matches('\n'),
                "RFC 8785 vector {name}"
            );
            checked += 1;
        }
        // Count asserted so a vector silently disappearing from disk shows up as
        // a failure rather than as a shorter, still-green run.
        assert_eq!(checked, 6, "all six official vectors must be present");
    }

    /// ES6 number serialization (RFC 8785 §3.2.2.3) — where implementations
    /// that use Rust's `ryu` instead of `ryu-js` diverge.
    #[test]
    fn es6_number_boundaries() {
        let cases: &[(&str, &str)] = &[
            ("0", "0"),
            ("-0", "0"),
            ("1e20", "100000000000000000000"),
            ("1e21", "1e+21"),
            ("1e-6", "0.000001"),
            ("1e-7", "1e-7"),
            ("1e30", "1e+30"),
            ("5e-324", "5e-324"),
            ("9007199254740992", "9007199254740992"),
            ("1.7976931348623157e308", "1.7976931348623157e+308"),
            ("2.2250738585072014e-308", "2.2250738585072014e-308"),
            ("1.0", "1"),
            ("100.0", "100"),
        ];
        for (input, expected) in cases {
            let value: serde_json::Value = serde_json::from_str(input).expect("parses");
            assert_eq!(
                &to_canonical_string(&value).expect("canonicalizes"),
                expected,
                "number {input}"
            );
        }
    }

    /// RFC 8785 sorts object keys by UTF-16 code unit, NOT by UTF-8 byte order.
    /// The two agree throughout the BMP and diverge above it, so this is the
    /// case that actually discriminates a correct implementation.
    #[test]
    fn keys_sort_by_utf16_code_unit_not_utf8_bytes() {
        let value: serde_json::Value =
            serde_json::from_str(r#"{"é":1,"😀":2,"a":3,"￿":4}"#).expect("parses");
        let canonical = to_canonical_string(&value).expect("canonicalizes");

        // UTF-16: a=0061, é=00E9, 😀=D83D DE00 (high surrogate), ￿=FFFF.
        // So the emoji sorts BEFORE U+FFFF. Naive UTF-8 byte order would put
        // U+FFFF (EF BF BF) before the emoji (F0 9F 98 80).
        assert_eq!(canonical, "{\"a\":3,\"é\":1,\"😀\":2,\"\u{ffff}\":4}");
        assert!(
            canonical.find('😀').unwrap() < canonical.find('\u{ffff}').unwrap(),
            "emoji must precede U+FFFF under UTF-16 ordering"
        );
    }

    /// §91.1 test 6: different digest domains produce different preimages.
    /// Checked over the full pairwise set — 105 pairs — because a sample leaves
    /// the untested pair as the one that collides.
    #[test]
    fn every_domain_pair_yields_a_distinct_digest() {
        let payload = json!({"same": "payload", "for": "every domain"});
        let mut digests = std::collections::BTreeMap::new();
        for domain in DigestDomain::ALL {
            let d = sha256_digest(domain, &payload).expect("digests");
            if let Some(other) = digests.insert(d.clone(), domain) {
                panic!("{domain:?} and {other:?} collided on {d}");
            }
        }
        assert_eq!(digests.len(), DigestDomain::ALL.len());
    }

    #[test]
    fn the_preimage_has_the_shape_the_sas_specifies() {
        let bytes = preimage_bytes(DigestDomain::Contract, &json!({"a": 1})).expect("preimage");
        assert_eq!(
            String::from_utf8(bytes).expect("utf-8"),
            r#"{"digest_domain":"oh.war/contract/v1","payload":{"a":1}}"#
        );
    }

    /// Key order in the source must not change the canonical output, which is
    /// the property that makes a digest a function of meaning rather than of
    /// how the JSON happened to be written.
    #[test]
    fn source_key_order_does_not_affect_the_digest() {
        let a: serde_json::Value = serde_json::from_str(r#"{"b":2,"a":1}"#).expect("parses");
        let b: serde_json::Value = serde_json::from_str(r#"{"a":1,"b":2}"#).expect("parses");
        assert_eq!(
            sha256_digest(DigestDomain::Manifest, &a).expect("digest"),
            sha256_digest(DigestDomain::Manifest, &b).expect("digest")
        );
    }

    /// Determinism asserted across two independent computations, not by
    /// comparing a value to itself.
    #[test]
    fn digests_are_stable_across_runs() {
        let payload = json!({"x": [1, 2, 3], "y": {"z": true}});
        let first = sha256_digest(DigestDomain::WarExport, &payload).expect("digest");
        let second = sha256_digest(DigestDomain::WarExport, &payload).expect("digest");
        assert_eq!(first, second);
        assert_eq!(first.len(), 64, "sha256 hex is 64 characters");
        assert!(first.chars().all(|c| c.is_ascii_hexdigit()));
    }
}

// SPDX-License-Identifier: Apache-2.0
//! Digest domains and domain-separated preimages (SAS §65).
//!
//! §65.2 requires that hashing operate on a domain-separated preimage:
//!
//! ```json
//! { "digest_domain": "oh.war/contract/v1", "payload": { } }
//! ```
//!
//! The reason is stated in the SAS and is worth repeating where the code lives:
//! two different semantic objects can serialise to identical JSON. A contract
//! and an artifact record that happen to share a shape would otherwise hash to
//! the same value, and a digest that collides across domains cannot be used to
//! prove which of the two was signed.
//!
//! # What is deliberately missing
//!
//! `sha256_hex` hashes bytes. It does NOT canonicalize a JSON value, because
//! canonicalization is RFC 8785 (§65.2) and the implementation of RFC 8785 binds
//! the wire format for every cross-system digest OpenWarrant will ever mint.
//! Choosing that library is an implementation ADR (§80), scheduled before
//! OW-WAR-0003 lands. Shipping a placeholder canonicalizer now would mint
//! digests that a later correction would silently invalidate.

use sha2::{Digest, Sha256};

/// The digest domains a conforming implementation must compute (§65).
///
/// All fifteen are listed here even though Phase 1 computes only a few: the
/// vocabulary is protocol surface, and a later phase adding a domain should be
/// an edit to this enum rather than a new string literal invented at a call site.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum DigestDomain {
    AtomSource,
    Manifest,
    CompositionRevision,
    WorkspaceBasis,
    SemanticGraph,
    Contract,
    ContextManifest,
    Dispatch,
    AttemptBasis,
    Artifact,
    GateBinding,
    GateRun,
    AssuranceCaseSnapshot,
    Resolution,
    WarExport,
    /// A verification bundle (slice C3).
    VerificationBundle,
}

impl DigestDomain {
    /// Every domain, in declaration order. Used by conformance tests.
    pub const ALL: [Self; 16] = [
        Self::AtomSource,
        Self::Manifest,
        Self::CompositionRevision,
        Self::WorkspaceBasis,
        Self::SemanticGraph,
        Self::Contract,
        Self::ContextManifest,
        Self::Dispatch,
        Self::AttemptBasis,
        Self::Artifact,
        Self::GateBinding,
        Self::GateRun,
        Self::AssuranceCaseSnapshot,
        Self::Resolution,
        Self::WarExport,
        Self::VerificationBundle,
    ];

    /// The stable URI written into the preimage's `digest_domain` field.
    #[must_use]
    pub const fn as_uri(self) -> &'static str {
        match self {
            Self::AtomSource => "oh.war/atom-source/v1",
            Self::Manifest => "oh.war/manifest/v1",
            Self::CompositionRevision => "oh.war/composition-revision/v1",
            Self::WorkspaceBasis => "oh.war/workspace-basis/v1",
            Self::SemanticGraph => "oh.war/semantic-graph/v1",
            Self::Contract => "oh.war/contract/v1",
            Self::ContextManifest => "oh.war/context-manifest/v1",
            Self::Dispatch => "oh.war/dispatch/v1",
            Self::AttemptBasis => "oh.war/attempt-basis/v1",
            Self::Artifact => "oh.war/artifact/v1",
            Self::GateBinding => "oh.war/gate-binding/v1",
            Self::GateRun => "oh.war/gate-run/v1",
            Self::AssuranceCaseSnapshot => "oh.war/assurance-case-snapshot/v1",
            Self::Resolution => "oh.war/resolution/v1",
            Self::WarExport => "oh.war/war-export/v1",
            Self::VerificationBundle => "oh.war/verification-bundle/v1",
        }
    }
}

/// SHA-256 over already-canonical bytes, lowercase hex.
///
/// §65.1: cross-system WAR digests use SHA-256 unless a later protocol revision
/// says otherwise, and the algorithm is always explicit.
#[must_use]
pub fn sha256_hex(bytes: &[u8]) -> String {
    let mut hasher = Sha256::new();
    hasher.update(bytes);
    let out = hasher.finalize();
    let mut hex = String::with_capacity(out.len() * 2);
    for byte in out {
        use std::fmt::Write as _;
        let _ = write!(hex, "{byte:02x}");
    }
    hex
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// §65 lists fifteen domains. If the SAS grows one, this fails and the
    /// vocabulary gets updated deliberately rather than drifting.
    #[test]
    fn all_sixteen_domains_are_present() {
        assert_eq!(DigestDomain::ALL.len(), 16);
    }

    /// §91.1 test 6: different digest domains produce different preimages.
    ///
    /// Enforced here at its root: no two domains may share a URI. If they did,
    /// domain separation would be decorative.
    #[test]
    fn domain_uris_are_unique() {
        let uris: BTreeSet<&str> = DigestDomain::ALL.iter().map(|d| d.as_uri()).collect();
        assert_eq!(
            uris.len(),
            DigestDomain::ALL.len(),
            "digest domain URIs must be pairwise distinct"
        );
    }

    #[test]
    fn domain_uris_are_namespaced_and_versioned() {
        for domain in DigestDomain::ALL {
            let uri = domain.as_uri();
            assert!(
                uri.starts_with("oh.war/"),
                "{uri} must use the oh.war family"
            );
            assert!(uri.ends_with("/v1"), "{uri} must carry an explicit version");
        }
    }

    /// Pinned against the published SHA-256 of the empty string and of "abc".
    /// A frozen external vector, not a value read back out of this
    /// implementation — an implementation-derived expectation would pass even
    /// if the hash were wrong.
    #[test]
    fn sha256_matches_published_vectors() {
        assert_eq!(
            sha256_hex(b""),
            "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855"
        );
        assert_eq!(
            sha256_hex(b"abc"),
            "ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad"
        );
    }
}

